import React, { useState } from "react";

const VisualizationSection = () => {
  const [image, setImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [title, setTitle] = useState("");
  const [graphMessage, setGraphMessage] = useState(""); // MESSAGE SUPPORT

  const fetchImage = async (endpoint, graphTitle) => {
    setLoading(true);
    setTitle(graphTitle);

    try {
      const endpointUrl = endpoint.startsWith("shap")
          ? `http://127.0.0.1:8000/explain/${endpoint}`
          : `http://127.0.0.1:8000/visualize/${endpoint}`;

      const res = await fetch(endpointUrl);
      const data = await res.json();

      // Backend returns:
      // { image: null, message: "Feature importance is only..." }
      if (data.image === null && data.message) {
        setGraphMessage(data.message);
        setImage(null);
      } else {
        setGraphMessage("");
        setImage(data.image);
      }
    } catch (err) {
      setGraphMessage("Failed to load visualization.");
      setImage(null);
    }

    setLoading(false);
  };

  return (
    <div
      style={{
        marginTop: "40px",
        padding: "30px",
        background: "linear-gradient(140deg, #a8edea, #fed6e3)",
        borderRadius: "18px",
        boxShadow: "0 5px 20px rgba(0,0,0,0.25)",
      }}
    >
      <h2
        style={{
          textAlign: "center",
          fontSize: "28px",
          marginBottom: "20px",
          fontWeight: "600",
        }}
      >
        📊 Visualization Dashboard
      </h2>

      {/* BUTTONS */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-around",
          flexWrap: "wrap",
          gap: "15px",
          marginBottom: "20px",
        }}
      >
        <button className="viz-btn" onClick={() => fetchImage("roc", "ROC Curve")}>
          ROC Curve
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("confusion_heatmap", "Confusion Matrix Heatmap")
          }
        >
          Confusion Heatmap
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("correlation_heatmap", "Correlation Heatmap")
          }
        >
          Correlation Heatmap
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("churn_distribution", "Churn Distribution")
          }
        >
          Churn Distribution
        </button>

        <button
          className="viz-btn"
          onClick={() =>
            fetchImage("feature_importance", "Feature Importance")
          }
        >
          Feature Importance
        </button>
        <button
        className="viz-btn"
        onClick={() => fetchImage("shap", "SHAP Summary Plot")}
      >
        SHAP Explainability
        </button>
        
      </div>

      {/* DISPLAY AREA */}
      <div style={{ textAlign: "center", marginTop: "25px" }}>
        {loading && (
          <p
            style={{
              fontSize: "18px",
              fontFamily: "monospace",
              color: "#444",
            }}
          >
            Loading Visualization...
          </p>
        )}

        {/* SHOW MESSAGE (Only for unsupported models like Logistic Regression) */}
        {graphMessage && !loading && (
          <div
            style={{
              marginTop: "20px",
              padding: "15px",
              background: "#ffffff",
              borderRadius: "12px",
              boxShadow: "0 3px 10px rgba(0,0,0,0.15)",
              fontSize: "18px",
              color: "#333",
              maxWidth: "600px",
              marginLeft: "auto",
              marginRight: "auto",
              whiteSpace: "pre-line",
            }}
          >
            {graphMessage}
          </div>
        )}

        {/* SHOW IMAGE */}
        {!loading && image && (
          <div>
            <h3 style={{ marginBottom: "15px" }}>{title}</h3>
            <img
              src={`data:image/png;base64,${image}`}
              alt={title}
              style={{
                maxWidth: "95%",
                borderRadius: "12px",
                boxShadow: "0 0 15px rgba(0,0,0,0.3)",
                marginTop: "20px",
              }}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default VisualizationSection;
